<?php

namespace MongoDB\BSON;

use stdClass;

/**
 * <div id="class.mongodb-bson-serializable" class="reference"> <h1 class="title">The MongoDB\BSON\Serializable interface</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-bson-serializable.intro">   <h2 class="title">简介</h2>   <p class="simpara">    Classes that implement this interface may return data to be serialized as a    BSON array or document in lieu of the object's public properties.   </p>  </div>  <div class="section" id="mongodb-bson-serializable.synopsis">   <h2 class="title">接口摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\BSON\Serializable</strong>     </span>     <span class="oointerface"><span class="modifier">implements</span>        <a href="https://php.net/manual/zh/class.mongodb-bson-type.php" class="interfacename">MongoDB\BSON\Type</a></span> {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-bson-serializable.bsonserialize.php" class="methodname" style="color:#CC7832">bsonSerialize</a></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="type MongoDB\BSON\Document" style="color:#EAB766">MongoDB\BSON\Document</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="type MongoDB\BSON\PackedArray" style="color:#EAB766">MongoDB\BSON\PackedArray</a></span></span></div>   }</div>  </div>  <div class="section">   <h2 class="title">更新日志</h2>   <table class="doctable informaltable">         <thead>      <tr>       <th>版本</th>       <th>说明</th>      </tr>     </thead>     <tbody class="tbody">             <tr>        <td>PECL mongodb 2.0.0</td>        <td>         之前声明为暂定的返回类型现在已被强制执行。        </td>       </tr>             <tr>        <td>PECL mongodb 1.15.0</td>        <td>         在 PHP 8.0 及更高版本中，方法的返回类型被声明为暂定（tentative），         这会导致在实现该接口但未声明相应返回类型的代码中触发弃用提示。         可以添加 <span class="code">#[ReturnTypeWillChange]</span> 属性来消除该弃用提示。        </td>       </tr>     </tbody>       </table>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\BSON\Serializable::bsonSerialize} — Provides an array or document to serialize as BSON</li></ul></div>
 * 
 * Classes that implement this interface may return data to be serialized as a BSON array or document in lieu of the object's public properties
 * @link https://php.net/manual/zh/class.mongodb-bson-serializable.php
 */
interface Serializable extends Type
{
    /**
 * <div id="mongodb-bson-serializable.bsonserialize" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\BSON\Serializable::bsonSerialize</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\BSON\Serializable::bsonSerialize</span> — <span class="dc-title">Provides an array or document to serialize as BSON</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-bson-serializable.bsonserialize-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">abstract</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\BSON\Serializable::bsonSerialize</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.stdclass.php" class="type stdClass" style="color:#EAB766">stdClass</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="type MongoDB\BSON\Document" style="color:#EAB766">MongoDB\BSON\Document</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="type MongoDB\BSON\PackedArray" style="color:#EAB766">MongoDB\BSON\PackedArray</a></span></span></div>  <p class="simpara">   Called during serialization of the object to BSON. The method must return an   <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>, <span class="classname"><a href="https://php.net/manual/zh/class.stdclass.php" class="classname">stdClass</a></span>, <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="classname">MongoDB\BSON\Document</a></span>,   or <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="classname">MongoDB\BSON\PackedArray</a></span>.  </p>  <p class="simpara">   Root documents (e.g. a   <span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-serializable.php" class="interfacename">MongoDB\BSON\Serializable</a></span> passed to   <span class="methodname" style="color:#CC7832">{@link MongoDB\BSON\Document::fromPHP()}</span>) will always be   serialized as a BSON document. For field values, associative arrays and   <span class="classname"><a href="https://php.net/manual/zh/class.stdclass.php" class="classname">stdClass</a></span> instances will be serialized as a BSON   document and sequential arrays (i.e. sequential, numeric indexes starting at   <span class="literal">0</span>) will be serialized as a BSON array.  </p>  <p class="simpara">   Users are encouraged to include an <span class="property">_id</span> property (e.g. a   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> initialized in the constructor)   when returning data for a BSON root document. In the absence of an   <span class="property">_id</span> property, the extension or server will generate a   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-objectid.php" class="classname">MongoDB\BSON\ObjectId</a></span> for insert or upsert   operations, respectively.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-bson-serializable.bsonserialize-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-bson-serializable.bsonserialize-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   An <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>, <span class="classname"><a href="https://php.net/manual/zh/class.stdclass.php" class="classname">stdClass</a></span>, <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="classname">MongoDB\BSON\Document</a></span>,   or <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="classname">MongoDB\BSON\PackedArray</a></span> to be serialized as a BSON   array or document.  </p> </div> <div class="refsect1 changelog" id="refsect1-mongodb-bson-serializable.bsonserialize-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">            <tr>        <td>PECL mongodb 2.0.0</td>        <td>         之前声明为暂定的返回类型现在已被强制执行。        </td>       </tr>     <tr>      <td>PECL mongodb 1.17.0</td>      <td>       <span class="simpara">        The return type was changed from <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span>.        Instead of <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span>, the return type now specifies <span class="classname"><a href="https://php.net/manual/zh/class.stdclass.php" class="classname">stdClass</a></span>.        Classes that implement this interface must be changed to no longer        declare an <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span> return type. As the return type is        tentative, a deprecation warning is emitted on PHP 8.1 and newer.       </span>       <span class="simpara">        In addition to the changes above, the extension now also supports        returning instances of <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-document.php" class="classname">MongoDB\BSON\Document</a></span>        and <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="classname">MongoDB\BSON\PackedArray</a></span>. Please note that        any <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-bson-packedarray.php" class="classname">MongoDB\BSON\PackedArray</a></span> instances returned        are silently converted to objects when stored as root documents. They        are stored as arrays when used as an embedded field value.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-bson-serializable.bsonserialize-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Serializable::bsonSerialize()</strong></span> returning an associative array for root document</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">class </span><span style="color: #9876AA">MyDocument </span><span style="color: #007700">implements </span><span style="color: #9876AA">MongoDB\BSON\Serializable<br></span><span style="color: #007700">{<br>    private </span><span style="color: #9876AA">\$id</span><span style="color: #007700">;<br><br>    function </span><span style="color: #9876AA">__construct</span><span style="color: #007700">()<br>    {<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">id </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\BSON\ObjectId</span><span style="color: #007700">;<br>    }<br><br>    function </span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">(): array<br>    {<br>        return [</span><span style="color: #DD0000">'_id' </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">id</span><span style="color: #007700">, </span><span style="color: #DD0000">'foo' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'bar'</span><span style="color: #007700">];<br>    }<br>}<br><br>echo </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(new </span><span style="color: #9876AA">MyDocument</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">{&nbsp;"_id"&nbsp;:&nbsp;{&nbsp;"\$oid"&nbsp;:&nbsp;"56cccdcada14d8755a58c591"&nbsp;},&nbsp;"foo"&nbsp;:&nbsp;"bar"&nbsp;}</blockquote></div>   </div>  </div>  <div class="example" id="example-2">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Serializable::bsonSerialize()</strong></span> returning a sequential array for root document</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">class </span><span style="color: #9876AA">MyArray </span><span style="color: #007700">implements </span><span style="color: #9876AA">MongoDB\BSON\Serializable<br></span><span style="color: #007700">{<br>    function </span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">(): array<br>    {<br>        return [</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">];<br>    }<br>}<br><br>echo </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(new </span><span style="color: #9876AA">MyArray</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">{&nbsp;"0"&nbsp;:&nbsp;1,&nbsp;"1"&nbsp;:&nbsp;2,&nbsp;"2"&nbsp;:&nbsp;3&nbsp;}</blockquote></div>   </div>  </div>  <div class="example" id="example-3">   <p><strong>示例 #3 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Serializable::bsonSerialize()</strong></span> returning an associative array for document field</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">class </span><span style="color: #9876AA">MyDocument </span><span style="color: #007700">implements </span><span style="color: #9876AA">MongoDB\BSON\Serializable<br></span><span style="color: #007700">{<br>    function </span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">(): array<br>    {<br>        return [</span><span style="color: #DD0000">'foo' </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">'bar'</span><span style="color: #007700">];<br>    }<br>}<br><br></span><span style="color: #9876AA">\$value </span><span style="color: #007700">= [</span><span style="color: #DD0000">'document' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MyDocument</span><span style="color: #007700">];<br><br>echo </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">{&nbsp;"document"&nbsp;:&nbsp;{&nbsp;"foo"&nbsp;:&nbsp;"bar"&nbsp;}&nbsp;}</blockquote></div>   </div>  </div>  <div class="example" id="example-4">   <p><strong>示例 #4 <span class="function"><strong style="color:#CC7832">MongoDB\BSON\Serializable::bsonSerialize()</strong></span> returning a sequential array for document field</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br></span><span style="color: #007700">class </span><span style="color: #9876AA">MyArray </span><span style="color: #007700">implements </span><span style="color: #9876AA">MongoDB\BSON\Serializable<br></span><span style="color: #007700">{<br>    function </span><span style="color: #9876AA">bsonSerialize</span><span style="color: #007700">(): array<br>    {<br>        return [</span><span style="color: #9876AA">1</span><span style="color: #007700">, </span><span style="color: #9876AA">2</span><span style="color: #007700">, </span><span style="color: #9876AA">3</span><span style="color: #007700">];<br>    }<br>}<br><br></span><span style="color: #9876AA">\$value </span><span style="color: #007700">= [</span><span style="color: #DD0000">'array' </span><span style="color: #007700">=&gt; new </span><span style="color: #9876AA">MyArray</span><span style="color: #007700">];<br><br>echo </span><span style="color: #9876AA">MongoDB\BSON\Document</span><span style="color: #007700">::</span><span style="color: #9876AA">fromPHP</span><span style="color: #007700">(</span><span style="color: #9876AA">\$value</span><span style="color: #007700">)-&gt;</span><span style="color: #9876AA">toRelaxedExtendedJSON</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">{&nbsp;"array"&nbsp;:&nbsp;[&nbsp;1,&nbsp;2,&nbsp;3&nbsp;]&nbsp;}</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-bson-serializable.bsonserialize-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\BSON\Unserializable::bsonUnserialize()} - Constructs the object from a BSON array or document</span></li>   <li><span class="interfacename"><a href="https://php.net/manual/zh/class.mongodb-bson-persistable.php" class="interfacename">MongoDB\BSON\Persistable</a></span></li>   <li><a href="https://php.net/manual/zh/mongodb.persistence.php" class="xref">Persisting Data</a></li>  </ul> </div></div>
 * 
     * Provides an array or document to serialize as BSON
     * Called during serialization of the object to BSON. The method must return an array or stdClass.
     * Root documents (e.g. a MongoDB\BSON\Serializable passed to MongoDB\BSON\fromPHP()) will always be serialized as a BSON document.
     * For field values, associative arrays and stdClass instances will be serialized as a BSON document and sequential arrays (i.e. sequential, numeric indexes starting at 0) will be serialized as a BSON array.
     * @link https://php.net/manual/zh/mongodb-bson-serializable.bsonserialize.php
     */
    public function bsonSerialize(): array|stdClass|Document|PackedArray;
}
